<script setup lang="ts">defineProps<{modelValue:string;label:string;options:{label:string;value:string}[]}>();defineEmits<{(e:'update:modelValue',value:string):void}>()</script><template><label class="field"><span>{{label}}</span><select :value="modelValue" @change="$emit('update:modelValue',($event.target as HTMLSelectElement).value)"><option v-for="o in options" :key="o.value" :value="o.value">{{o.label}}</option></select></label></template><style scoped>.field{display:grid;gap:7px;font-size:14px;font-weight:600}select{min-height:44px;padding:0 12px;border:1px solid var(--ds-border-strong);border-radius:var(--ds-radius-md);background:var(--ds-surface);color:var(--ds-text)}</style>